CREATE OR REPLACE TRIGGER TDMS.TRIG_MKT
      AFTER INSERT OR DELETE OR UPDATE ON TDMS.MKT FOR EACH ROW
DISABLE
BEGIN
      IF INSERTING THEN
        INSERT INTO AHN.LOG_MKT(MKT_CODE, MKT_DESC, MPO_CODE, CHANGE_TYPE, UPDATE_TIME)
        VALUES(:NEW.MKT_CODE, :NEW.MKT_DESC, :NEW.MPO_CODE,'I', SYSDATE);
        INSERT INTO SMIS.MKT(MPO_CODE, MKT_CODE, MKT_DESC, USER_ID, ENTER_DT,IS_ACTIVE)
        VALUES (:NEW.MPO_CODE, :NEW.MKT_CODE, :NEW.MKT_DESC, :NEW.USER_ID, :NEW.ENTER_DT,:NEW.IS_ACTIVE);
        INSERT INTO PRES_SURVEY_SPOT(MPO_CODE, SPOT_ID, SPOT_NAME, USER_ID, ENTER_DT, MKT_CODE)
        VALUES (:NEW.MPO_CODE,SPOT_ID_GEN_FUNC,:NEW.MKT_DESC,:NEW.USER_ID,:NEW.ENTER_DT,:NEW.MKT_CODE);
     ELSIF UPDATING THEN
        INSERT INTO AHN.LOG_MKT(MKT_CODE, MKT_DESC, MPO_CODE, CHANGE_TYPE, UPDATE_TIME)
        values (:NEW.MKT_CODE, :NEW.MKT_DESC, :NEW.MPO_CODE,'U', SYSDATE);
        UPDATE SMIS.MKT
        SET MPO_CODE=:NEW.MPO_CODE,MKT_DESC=:NEW.MKT_DESC
        WHERE MKT_CODE=:OLD.MKT_CODE;
        UPDATE PRES_SURVEY_SPOT
        SET SPOT_NAME=:NEW.MKT_DESC, MPO_CODE=:NEW.MPO_CODE
        WHERE MKT_CODE=:OLD.MKT_CODE;
        --UPDATE DOC_MASTER
        --SET MPO_CODE=:NEW.MPO_CODE,MKT_CODE=:NEW.MKT_CODE
        --WHERE MPO_CODE=:OLD.MPO_CODE AND MKT_CODE=:OLD.MKT_CODE;
     ELSE
        INSERT INTO AHN.LOG_MKT(MKT_CODE, MKT_DESC, MPO_CODE, CHANGE_TYPE, UPDATE_TIME)
       values (:OLD.MKT_CODE, :OLD.MKT_DESC, :OLD.MPO_CODE, 'I', SYSDATE);
     END IF;
END;
/


CREATE OR REPLACE TRIGGER TDMS.TRIG_CHEMIST
      AFTER INSERT OR DELETE OR UPDATE ON tdms.CUSTOMER
      FOR EACH ROW
DISABLE
BEGIN
      IF INSERTING THEN
        INSERT INTO AHN.LOG_CUSTOMER(CUST_CODE, CUST_NAME, MPO_CODE, MKT_CODE, CHANGE_TYPE, UPDATE_TIME)
        values (:NEW.CUST_CODE, :NEW.CUST_NAME, :NEW.MPO_CODE, :NEW.MKT_CODE, 'I', SYSDATE);
     ELSIF UPDATING THEN
        INSERT INTO AHN.LOG_CUSTOMER(CUST_CODE, CUST_NAME, MPO_CODE, MKT_CODE, CHANGE_TYPE, UPDATE_TIME)
        values (:NEW.CUST_CODE, :NEW.CUST_NAME, :NEW.MPO_CODE, :NEW.MKT_CODE,'U', SYSDATE);
     ELSE
        INSERT INTO AHN.LOG_CUSTOMER(CUST_CODE, CUST_NAME, MPO_CODE, MKT_CODE, CHANGE_TYPE, UPDATE_TIME)
  values (:OLD.CUST_CODE, :OLD.CUST_NAME, :OLD.MPO_CODE, :OLD.MKT_CODE,'D', SYSDATE);
     END IF;
    END;
/


CREATE OR REPLACE TRIGGER TDMS.TRIG_PS_SPOT
