     ELSE
        INSERT INTO AHN.LOG_PS_SPOT
  values (:OLD.SPOT_ID, :OLD.SPOT_NAME,:OLD.MPO_CODE,'D', SYSDATE);
     END IF;
    END;
/


CREATE OR REPLACE TRIGGER TDMS.CUST_INFO_VALID_TRIG
  BEFORE UPDATE OF MKT_CODE ON TDMS.CUSTOMER   FOR EACH ROW
DISABLE
DECLARE
 VSTAT NUMBER;
BEGIN
IF :OLD.MPO_CODE=:NEW.MPO_CODE THEN
  SELECT COUNT(*)
  INTO VSTAT
  FROM TDMS.MKT
  WHERE MKT_CODE=NVL(:NEW.MKT_CODE,'000') AND MPO_CODE=:OLD.MPO_CODE;
IF VSTAT=0 THEN
 RAISE_APPLICATION_ERROR( -20001,'Ivalid Market code : '||:NEW.MKT_CODE||' aganist MPO Code: '||:OLD.MPO_CODE||'. Please contact with IT');
END IF;
ELSE
  SELECT COUNT(*)
  INTO VSTAT
  FROM TDMS.MKT
  WHERE MKT_CODE=NVL(:NEW.MKT_CODE,'000') AND MPO_CODE=:NEW.MPO_CODE;
IF VSTAT=0 THEN
 RAISE_APPLICATION_ERROR( -20001,'Ivalid Market code : '||:NEW.MKT_CODE||' aganist MPO Code: '||:OLD.MPO_CODE||'. Please contact with IT');
END IF;
END IF;
END;
/


CREATE OR REPLACE TRIGGER TDMS.DCC_CUST_SP_PCT_HIST_TIG
AFTER UPDATE ON TDMS.DCC_CUST_SP_PCT FOR EACH ROW
