INSERT INTO  DCC_CUST_SP_PCT_HIST(MPO_CODE, CUST_CODE, BANK_ACC_NAME, MON_TARGET, AGREEMENT_PERIOD, PAYMENT_MODE, ITEM_NAME, AMOUNT, DIS_PCT, IS_ACTIVE, USER_ID, ENTER_DT)
VALUES(:OLD.MPO_CODE, :OLD.CUST_CODE, :OLD.BANK_ACC_NAME, :OLD.MON_TARGET, :OLD.AGREEMENT_PERIOD, :OLD.PAYMENT_MODE, :OLD.ITEM_NAME, :OLD.AMOUNT, :OLD.DIS_PCT, :OLD.IS_ACTIVE, :OLD.USER_ID, :OLD.ENTER_DT);
END;
/


