CREATE OR REPLACE TRIGGER TDMS.cust_type_trig
AFTER  update of CUST_TYPE  ON TDMS.CUSTOMER FOR EACH ROW
BEGIN
    IF updating THEN
        UPDATE smis.CUSTOMER 
        SET CUST_TYPE   = :NEW.CUST_TYPE
        WHERE cust_CODE = :old.cust_CODE;
        UPDATE tdms.cust_cr_Limit_2017  
        SET CUST_TYPE   = :NEW.CUST_TYPE
        WHERE cust_CODE = :old.cust_CODE;
     END IF; 
END;
/


CREATE OR REPLACE TRIGGER TDMS.TRIG_CUST_CR_LIMIT_2017
      AFTER INSERT OR DELETE OR UPDATE ON TDMS.CUST_CR_LIMIT_2017       FOR EACH ROW
DISABLE
BEGIN
      IF INSERTING THEN
        INSERT INTO AHN.LOG_CUST_CR_LIMIT_2017
        values (:NEW.CUST_CODE,SYSDATE,'I');
     ELSIF UPDATING THEN
        INSERT INTO AHN.LOG_CUST_CR_LIMIT_2017
          values  (:NEW.CUST_CODE,SYSDATE,'U');
     ELSE
        INSERT INTO AHN.LOG_CUST_CR_LIMIT_2017
      values  (:old.CUST_CODE,SYSDATE,'D');
     END IF;
    END;
/


CREATE OR REPLACE TRIGGER TDMS.SPS_INS_UP_TRIG 
AFTER INSERT OR UPDATE OF IS_ACTIVE ON TDMS.DOC_MON_HON_MAIN FOR EACH ROW
DISABLE
DECLARE
    VSTAT NUMBER;
    MPOC VARCHAR2(5);
    MKTC VARCHAR2(6);
BEGIN
    IF SUBSTR(:NEW.DOC_CODE,1,2)<>'AS' THEN

        IF INSERTING THEN
            IF :NEW.IS_ACTIVE='Y' THEN 
                SELECT COUNT(*) 
                INTO VSTAT
                FROM DOC_MASTER_MRAD WHERE DOC_CODE=:NEW.DOC_CODE;
                     IF VSTAT=0 THEN
                      SELECT AHN_MPO_RET_FUNC(A.MPO_CODE) MPO, A.MKT_CODE
                      INTO MPOC,MKTC
                      FROM DOC_MASTER A, SD_MPO B 
                      WHERE A.MPO_CODE=B.MPO_CODE
                      AND   A.DOC_CODE=:NEW.DOC_CODE;
                      
                      INSERT INTO DOC_MASTER_MRAD
                         (DOC_CODE, DOC_MPO, DOC_MKT, TMO_MPO, IS_ACTIVE, IS_SPS)
                      VALUES
                         (:NEW.DOC_CODE,:NEW.MPO_CODE,MKTC,MPOC,'Y','Y');
                     END IF;
            END IF;
        ELSIF UPDATING THEN
            IF :NEW.IS_ACTIVE='Y' THEN 
              UPDATE DOC_MASTER_MRAD
                SET IS_ACTIVE='Y' 
              WHERE DOC_CODE=:NEW.DOC_CODE;
            ELSIF :NEW.IS_ACTIVE='N' THEN
              UPDATE DOC_MASTER_MRAD
                SET IS_ACTIVE='N' 
              WHERE DOC_CODE=:NEW.DOC_CODE;
            END IF;
         END IF;
    END IF;
END;
/


