CREATE OR REPLACE TRIGGER TDMS.DOC_INFO_VALID_TRIG
  BEFORE UPDATE OF MKT_CODE ON TDMS.DOC_MASTER   FOR EACH ROW
DISABLE
DECLARE
 VSTAT NUMBER;
BEGIN
IF :OLD.MPO_CODE=:NEW.MPO_CODE THEN
  SELECT COUNT(*)
  INTO VSTAT
  FROM TDMS.MKT
  WHERE MKT_CODE=NVL(:NEW.MKT_CODE,'000') AND MPO_CODE=:OLD.MPO_CODE;
IF VSTAT=0 THEN
 RAISE_APPLICATION_ERROR( -20001,'Ivalid Market code : '||:NEW.MKT_CODE||' aganist MPO Code: '||:OLD.MPO_CODE||'. Please contact with IT');
END IF;
ELSE
  SELECT COUNT(*)
  INTO VSTAT
  FROM TDMS.MKT
  WHERE MKT_CODE=NVL(:NEW.MKT_CODE,'000') AND MPO_CODE=:NEW.MPO_CODE;
IF VSTAT=0 THEN
 RAISE_APPLICATION_ERROR( -20001,'Ivalid Market code : '||:NEW.MKT_CODE||' aganist MPO Code: '||:OLD.MPO_CODE||'. Please contact with IT');
END IF;
END IF;
END;
/


CREATE OR REPLACE TRIGGER TDMS.TRIG_DOCTOR
      AFTER INSERT OR DELETE OR UPDATE ON TDMS.DOC_MASTER       FOR EACH ROW
DISABLE
BEGIN
      IF INSERTING THEN
        INSERT INTO AHN.LOG_DOC_MASTER
        values (:NEW.DOC_CODE, :NEW.DOC_NAME, :NEW.MPO_CODE, :NEW.MKT_CODE, 'I', SYSDATE, :NEW.USER_ID);
     ELSIF UPDATING THEN
        INSERT INTO AHN.LOG_DOC_MASTER
        values (:NEW.DOC_CODE, :NEW.DOC_NAME, :NEW.MPO_CODE, :NEW.MKT_CODE,'U', SYSDATE, :NEW.USER_ID);
     ELSE
        INSERT INTO AHN.LOG_DOC_MASTER
  values (:OLD.DOC_CODE, :OLD.DOC_NAME,:OLD.MPO_CODE, :OLD.MKT_CODE,'D', SYSDATE, :OLD.USER_ID);
     END IF;
    END;
/


CREATE OR REPLACE TRIGGER TDMS.DOC_MASTER_LOYALTY_TRIG
AFTER INSERT OR UPDATE OF LOYALTY_STATUS ON TDMS.DOC_MASTER FOR EACH ROW
DISABLE
DECLARE 
VSTAT NUMBER;
BEGIN
IF INSERTING THEN
IF :NEW.LOYALTY_STATUS IS NULL THEN
INSERT INTO DOC_MASTER_LOYALTY_STATUS(MNYR, DOC_CODE, LOYALTY_STATUS, ENTRY_DT, USER_ID)
VALUES (TRUNC(SYSDATE,'MON'),:NEW.DOC_CODE,:NEW.LOYALTY_STATUS, :NEW.ENTER_DT,:NEW.USER_ID);
ELSIF UPDATING THEN
SELECT COUNT(*)
INTO VSTAT
FROM DOC_MASTER_LOYALTY_STATUS
WHERE DOC_CODE=:OLD.DOC_CODE AND TRUNC(MNYR)=TRUNC(SYSDATE,'MON');
IF VSTAT=0 THEN
INSERT INTO DOC_MASTER_LOYALTY_STATUS(MNYR, DOC_CODE, LOYALTY_STATUS, ENTRY_DT, USER_ID)
VALUES (TRUNC(SYSDATE,'MON'),:NEW.DOC_CODE,:NEW.LOYALTY_STATUS, :NEW.ENTER_DT,:NEW.USER_ID);
ELSIF VSTAT>0 THEN
UPDATE DOC_MASTER_LOYALTY_STATUS
SET LOYALTY_STATUS=:NEW.LOYALTY_STATUS
WHERE DOC_CODE=:OLD.DOC_CODE AND TRUNC(MNYR)=TRUNC(SYSDATE,'MON');
END IF;
END IF;
END IF;
END;
/


